(() => {
  const root = document.documentElement;
  const updateConceptHeader = () => {
    const progress = Math.min(window.scrollY / 180, 1);
    root.style.setProperty("--concept-header-progress", progress.toFixed(3));
  };

  updateConceptHeader();
  window.addEventListener("scroll", updateConceptHeader, { passive: true });
})();

(() => {
  const card = document.querySelector("[data-therapist-rotator]");
  if (!card || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

  const prefix = window.location.pathname.startsWith("/Bay-Area-Professional-Counseling-Site/")
    ? "/Bay-Area-Professional-Counseling-Site"
    : "";
  const therapists = [
    {
      name: "Lacey",
      role: "Owner & Licensed Professional Counselor",
      summary: "Helping adults, couples, and families find hope through compassionate care.",
      image: "/assets/IMG_0051-99db6be59a41.jpg",
      alt: "Lacey Moore",
      href: "/quiet-coast/lacey/"
    },
    {
      name: "Alexa",
      role: "Licensed Professional Counselor",
      summary: "Supporting individuals, families, and clients navigating addiction or transition.",
      image: "/assets/IMG_9906-e7cd05e5faf2.jpg",
      alt: "Alexa Da Rosa",
      href: "/quiet-coast/alexa/"
    },
    {
      name: "Cindy",
      role: "Licensed Professional Counselor",
      summary: "Bringing experienced care for adults, couples, and adolescents.",
      image: "/assets/IMG_0006-2-1fecee2be4a7.jpg",
      alt: "Cindy Perronne",
      href: "/quiet-coast/cindy/"
    },
    {
      name: "Kayla",
      role: "Licensed Professional Counselor",
      summary: "Offering restorative support for children, teens, adults, and families.",
      image: "/assets/Kayla-pic-ef9bd584ab26.jpg",
      alt: "Kayla Whatley",
      href: "/quiet-coast/kayla/"
    },
    {
      name: "Leigh",
      role: "Associate Licensed Counselor",
      summary: "Providing compassionate support for perinatal care, grief, anxiety, and trauma.",
      image: "/assets/L.photo-b9534d3c0366.jpg",
      alt: "Leigh Mohorn",
      href: "/quiet-coast/leigh/"
    }
  ];

  const image = card.querySelector("[data-therapist-image]");
  const heading = card.querySelector("[data-therapist-heading]");
  const role = card.querySelector("[data-therapist-role]");
  const summary = card.querySelector("[data-therapist-summary]");
  const link = card.querySelector("[data-therapist-link]");
  let index = 0;

  function setTherapist(therapist) {
    image.src = prefix + therapist.image;
    image.alt = therapist.alt;
    heading.textContent = "Meet " + therapist.name;
    role.textContent = therapist.role;
    summary.textContent = therapist.summary;
    link.href = prefix + therapist.href;
  }

  window.setInterval(() => {
    index = (index + 1) % therapists.length;
    card.classList.add("is-fading");
    window.setTimeout(() => {
      setTherapist(therapists[index]);
      window.requestAnimationFrame(() => {
        card.classList.remove("is-fading");
      });
    }, 720);
  }, 5200);
})();

